package branching

import (
	"context"
	"database/sql"
	"fmt"
	"strings"

	"github.com/google/uuid"

	appsession "github.com/TrebuchetDynamics/gormes-agent/internal/app/session"
	"github.com/TrebuchetDynamics/gormes-agent/internal/llm"
	sessionpkg "github.com/TrebuchetDynamics/gormes-agent/internal/persistence/session"
	"github.com/TrebuchetDynamics/gormes-agent/internal/persistence/transcript"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/local/sessionadapters/switching"
)

type BranchIDFunc func() string

func NewSessionBranchFunc(rootCtx context.Context, metadata sessionpkg.MetadataWriter, resume func(string, []llm.Message) error) tui.SessionBranchFunc {
	return NewSessionBranchFuncWithID(rootCtx, metadata, resume, NewSessionBranchID)
}

func NewSessionBranchFuncWithID(rootCtx context.Context, metadata sessionpkg.MetadataWriter, resume func(string, []llm.Message) error, newID BranchIDFunc) tui.SessionBranchFunc {
	switcher := switching.NewResidentSessionSwitcher(rootCtx, resume)
	return func(ctx context.Context, req tui.BranchRequest) (tui.BranchResult, error) {
		ctx = switcher.Context(ctx)
		if err := switcher.RequireResume(); err != nil {
			return tui.BranchResult{}, err
		}
		if metadata == nil {
			return tui.BranchResult{}, fmt.Errorf("metadata store unavailable")
		}
		childID := strings.TrimSpace(newID())
		if childID == "" {
			return tui.BranchResult{}, fmt.Errorf("child session id unavailable")
		}
		db, err := appsession.OpenSessionDirectoryDB()
		if err != nil {
			return tui.BranchResult{}, err
		}
		defer db.Close()

		forked, err := sessionpkg.Fork(ctx, metadata, transcriptTurnCopier{db: db}, sessionpkg.ForkRequest{
			ParentSessionID: req.ParentSessionID,
			ChildSessionID:  childID,
			Title:           req.Title,
		})
		if err != nil {
			return tui.BranchResult{}, err
		}

		if _, err := switcher.SwitchWithTranscriptDB(ctx, db, forked.SessionID, req.History); err != nil {
			return tui.BranchResult{}, err
		}

		return tui.BranchResult{
			SessionID:        forked.SessionID,
			ParentSessionID:  forked.ParentSessionID,
			Title:            forked.Title,
			TranscriptCopied: forked.TranscriptCopied,
		}, nil
	}
}

type transcriptTurnCopier struct {
	db *sql.DB
}

func (c transcriptTurnCopier) CopyTurns(ctx context.Context, parentSessionID, childSessionID string) (int, error) {
	return transcript.ForkTurns(ctx, c.db, parentSessionID, childSessionID)
}

func NewSessionBranchID() string {
	return "branch-" + strings.ReplaceAll(uuid.NewString(), "-", "")
}

package directory

import (
	"context"
	"errors"
	"fmt"
	"strings"

	appsession "github.com/TrebuchetDynamics/gormes-agent/internal/app/session"
	"github.com/TrebuchetDynamics/gormes-agent/internal/config"
	"github.com/TrebuchetDynamics/gormes-agent/internal/llm"
	sessionpkg "github.com/TrebuchetDynamics/gormes-agent/internal/persistence/session"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/local/sessionadapters/switching"
)

func NewSessionDirectoryFunc(ctx context.Context) tui.SessionDirectoryFunc {
	return func(limit int) ([]tui.SessionDirectoryEntry, error) {
		if limit <= 0 {
			limit = 20
		}
		db, err := appsession.OpenSessionDirectoryDB()
		if err != nil {
			if strings.Contains(err.Error(), "memory database not found") {
				return nil, nil
			}
			return nil, err
		}
		defer db.Close()

		sessions, err := sessionpkg.ListDirectorySessions(ctx, db, sessionpkg.DirectoryFilter{Limit: limit})
		if err != nil {
			return nil, err
		}
		sessions = appsession.ApplySessionMirrorSources(sessions, config.SessionIndexMirrorPath())
		out := make([]tui.SessionDirectoryEntry, 0, len(sessions))
		for _, item := range sessions {
			out = append(out, tui.SessionDirectoryEntry{
				ID:           item.ID,
				Title:        item.Title,
				Preview:      item.Preview,
				Source:       item.Source,
				LastActiveAt: item.LastActiveAt,
				MessageCount: item.MessageCount,
			})
		}
		return out, nil
	}
}

func NewSessionResumeFunc(rootCtx context.Context, resume func(string, []llm.Message) error) tui.SessionResumeFunc {
	switcher := switching.NewResidentSessionSwitcher(rootCtx, resume)
	return func(ctx context.Context, query string) (tui.SessionResumeResult, error) {
		ctx = switcher.Context(ctx)
		query = strings.TrimSpace(query)
		if query == "" {
			return tui.SessionResumeResult{}, fmt.Errorf("session id or prefix required")
		}
		if err := switcher.RequireResume(); err != nil {
			return tui.SessionResumeResult{}, err
		}
		db, err := appsession.OpenSessionDirectoryDB()
		if err != nil {
			return tui.SessionResumeResult{}, err
		}
		defer db.Close()

		resolved, err := sessionpkg.ResolveSessionIDPrefix(ctx, db, query)
		if err != nil {
			if errors.Is(err, sessionpkg.ErrSessionNotFound) {
				return tui.SessionResumeResult{}, fmt.Errorf("session %q not found", query)
			}
			if errors.Is(err, sessionpkg.ErrSessionPrefixAmbiguous) {
				return tui.SessionResumeResult{}, fmt.Errorf("session prefix %q is ambiguous: %w", query, err)
			}
			return tui.SessionResumeResult{}, err
		}

		history, err := switcher.SwitchWithTranscriptDB(ctx, db, resolved, nil)
		if err != nil {
			return tui.SessionResumeResult{}, err
		}
		return tui.SessionResumeResult{SessionID: resolved, History: history}, nil
	}
}

package switching

import (
	"context"
	"database/sql"
	"fmt"

	"github.com/TrebuchetDynamics/gormes-agent/internal/llm"
	"github.com/TrebuchetDynamics/gormes-agent/internal/persistence/transcript"
)

type ResumeFunc func(string, []llm.Message) error

type ResidentSessionSwitcher struct {
	rootCtx context.Context
	resume  ResumeFunc
}

func NewResidentSessionSwitcher(rootCtx context.Context, resume ResumeFunc) ResidentSessionSwitcher {
	return ResidentSessionSwitcher{rootCtx: rootCtx, resume: resume}
}

func (s ResidentSessionSwitcher) RequireResume() error {
	if s.resume == nil {
		return fmt.Errorf("kernel resume unavailable")
	}
	return nil
}

func (s ResidentSessionSwitcher) Context(ctx context.Context) context.Context {
	return ContextWithRootFallback(s.rootCtx, ctx)
}

func ContextWithRootFallback(rootCtx, ctx context.Context) context.Context {
	if ctx != nil {
		return ctx
	}
	if rootCtx != nil {
		return rootCtx
	}
	return context.Background()
}

func (s ResidentSessionSwitcher) SwitchWithTranscriptDB(ctx context.Context, db *sql.DB, sessionID string, history []llm.Message) ([]llm.Message, error) {
	if err := s.RequireResume(); err != nil {
		return nil, err
	}
	ctx = s.Context(ctx)
	resolvedHistory := CloneHermesMessages(history)
	if len(resolvedHistory) == 0 {
		messages, err := transcript.LoadMessages(ctx, db, sessionID)
		if err != nil {
			return nil, err
		}
		resolvedHistory = HermesMessagesFromTranscript(messages)
	}
	if err := s.resume(sessionID, resolvedHistory); err != nil {
		return nil, err
	}
	return resolvedHistory, nil
}

func HermesMessagesFromTranscript(messages []transcript.Message) []llm.Message {
	if len(messages) == 0 {
		return nil
	}
	out := make([]llm.Message, 0, len(messages))
	for _, msg := range messages {
		out = append(out, llm.Message{Role: msg.Role, Content: msg.Content})
	}
	return out
}

func CloneHermesMessages(messages []llm.Message) []llm.Message {
	if len(messages) == 0 {
		return nil
	}
	out := make([]llm.Message, len(messages))
	for i, msg := range messages {
		out[i] = msg
		out[i].ContentParts = append([]llm.MessageContentPart(nil), msg.ContentParts...)
	}
	return out
}

package titleops

import (
	"context"
	"strings"
	"time"

	"github.com/TrebuchetDynamics/gormes-agent/internal/persistence/session"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui"
)

func NewSessionTitleFunc(ctx context.Context, smap *session.BoltMap) tui.SessionTitleFunc {
	if smap == nil {
		return nil
	}
	return func(sessionID, title string) (tui.SessionTitleResult, error) {
		sessionID = strings.TrimSpace(sessionID)
		title = strings.TrimSpace(title)
		if title == "" {
			meta, ok, err := smap.GetMetadata(ctx, sessionID)
			if err != nil || !ok {
				return tui.SessionTitleResult{}, err
			}
			return tui.SessionTitleResult{Title: meta.Title}, nil
		}
		if err := smap.PutMetadata(ctx, session.Metadata{
			SessionID:        sessionID,
			Title:            title,
			TitleManuallySet: true,
			UpdatedAt:        time.Now().Unix(),
		}); err != nil {
			return tui.SessionTitleResult{}, err
		}
		return tui.SessionTitleResult{Title: title}, nil
	}
}

package treeops

import (
	"context"
	"errors"
	"strings"
	"time"

	appsession "github.com/TrebuchetDynamics/gormes-agent/internal/app/session"
	sessionpkg "github.com/TrebuchetDynamics/gormes-agent/internal/persistence/session"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/local/sessionadapters/switching"
)

const sessionTreeLimit = 200

func NewSessionTreeFunc(rootCtx context.Context, metadata *sessionpkg.BoltMap) tui.SessionTreeFunc {
	return func(ctx context.Context, req tui.SessionTreeRequest) (tui.SessionTreeResult, error) {
		ctx = switching.ContextWithRootFallback(rootCtx, ctx)
		db, err := appsession.OpenSessionDirectoryDB()
		if err != nil {
			if strings.Contains(err.Error(), "memory database not found") {
				return tui.SessionTreeResult{}, nil
			}
			return tui.SessionTreeResult{}, err
		}
		defer db.Close()

		var metas []sessionpkg.Metadata
		var ledgerMeta sessionpkg.LedgerMetadataReader
		if metadata != nil {
			ledgerMeta = metadata
			metas, err = metadata.ListAllMetadata(ctx)
			if err != nil {
				return tui.SessionTreeResult{}, err
			}
		}
		seen := map[string]struct{}{}
		ledgers := map[string]sessionpkg.SessionLedger{}
		directory, err := sessionpkg.ListDirectorySessions(ctx, db, sessionpkg.DirectoryFilter{Limit: sessionTreeLimit})
		if err != nil {
			return tui.SessionTreeResult{}, err
		}
		for _, entry := range directory {
			id := strings.TrimSpace(entry.ID)
			if id == "" {
				continue
			}
			seen[id] = struct{}{}
			ledger, err := sessionpkg.ReadSessionLedger(ctx, db, ledgerMeta, id)
			if err != nil {
				if errors.Is(err, sessionpkg.ErrSessionNotFound) {
					continue
				}
				return tui.SessionTreeResult{}, err
			}
			ledgers[id] = ledger
		}
		for _, meta := range metas {
			id := strings.TrimSpace(meta.SessionID)
			if id == "" {
				continue
			}
			if _, ok := seen[id]; ok {
				continue
			}
			seen[id] = struct{}{}
		}

		tree := sessionpkg.BuildSessionTree(metas, ledgers, sessionpkg.TreeOptions{ActiveSessionID: req.ActiveSessionID, Filter: sessionpkg.TreeFilter(req.Filter)})
		return sessionTreeResult(tree), nil
	}
}

func NewSessionTreeLabelFunc(rootCtx context.Context, metadata *sessionpkg.BoltMap) tui.SessionTreeLabelFunc {
	if metadata == nil {
		return nil
	}
	return func(ctx context.Context, req tui.SessionTreeLabelRequest) (tui.SessionTreeLabelResult, error) {
		ctx = switching.ContextWithRootFallback(rootCtx, ctx)
		sessionID := strings.TrimSpace(req.SessionID)
		meta, _, err := metadata.GetMetadata(ctx, sessionID)
		if err != nil {
			return tui.SessionTreeLabelResult{}, err
		}
		labels := append([]string(nil), meta.Labels...)
		label := strings.TrimSpace(req.Label)
		switch strings.ToLower(strings.TrimSpace(req.Action)) {
		case "set":
			if label != "" && !containsFoldString(labels, label) {
				labels = append(labels, label)
			}
		case "clear":
			if label == "" {
				labels = nil
			} else {
				labels = removeFoldString(labels, label)
			}
		}
		labels, err = metadata.SetLabels(ctx, sessionID, labels, time.Now())
		if err != nil {
			return tui.SessionTreeLabelResult{}, err
		}
		return tui.SessionTreeLabelResult{SessionID: sessionID, Labels: labels}, nil
	}
}

func NewSessionTreeRestoreFunc(rootCtx context.Context) tui.SessionTreeRestoreFunc {
	return func(ctx context.Context, req tui.SessionTreeRestoreRequest) (tui.SessionTreeRestoreResult, error) {
		ctx = switching.ContextWithRootFallback(rootCtx, ctx)
		db, err := appsession.OpenSessionDirectoryDB()
		if err != nil {
			return tui.SessionTreeRestoreResult{}, err
		}
		defer db.Close()
		ledger, err := sessionpkg.ReadSessionLedger(ctx, db, nil, req.SessionID)
		if err != nil {
			return tui.SessionTreeRestoreResult{}, err
		}
		text, evidence := sessionpkg.ReplayPromptFromLedger(ledger, req.MessageID)
		return tui.SessionTreeRestoreResult{Text: text, Editable: evidence == "", Evidence: evidence}, nil
	}
}

func sessionTreeResult(tree sessionpkg.SessionTree) tui.SessionTreeResult {
	out := tui.SessionTreeResult{Filter: string(tree.Filter), ActiveSessionID: tree.ActiveSessionID}
	out.Entries = make([]tui.SessionTreeEntry, 0, len(tree.Entries))
	for _, entry := range tree.Entries {
		outEntry := tui.SessionTreeEntry{
			ID:          entry.SessionID,
			ParentID:    entry.ParentSessionID,
			LineageKind: entry.LineageKind,
			Title:       entry.Title,
			Labels:      append([]string(nil), entry.Labels...),
			UpdatedAt:   entry.UpdatedAt,
			Depth:       entry.Depth,
			Active:      entry.Active,
			Status:      entry.Status,
		}
		for _, msg := range entry.Messages {
			outEntry.Messages = append(outEntry.Messages, tui.SessionTreeMessage{
				ID:       msg.ID,
				Role:     msg.Role,
				Content:  msg.Content,
				Evidence: msg.ReplayUnavailable,
			})
		}
		out.Entries = append(out.Entries, outEntry)
	}
	return out
}

func containsFoldString(values []string, value string) bool {
	for _, candidate := range values {
		if strings.EqualFold(strings.TrimSpace(candidate), strings.TrimSpace(value)) {
			return true
		}
	}
	return false
}

func removeFoldString(values []string, value string) []string {
	out := values[:0]
	for _, candidate := range values {
		if strings.EqualFold(strings.TrimSpace(candidate), strings.TrimSpace(value)) {
			continue
		}
		out = append(out, candidate)
	}
	return out
}

